/**
 * Clean SVG badges for engineering career roles
 */
export function RoleIcon({ role, className = "w-5 h-5" }: { role: string; className?: string }) {
  const r = role.toLowerCase().trim();

  if (r.includes("front")) {
    return (
      <svg viewBox="0 0 24 24" className={className} fill="none" aria-label="Frontend Engineering">
        <rect x="3" y="4" width="18" height="16" rx="3" stroke="#A855F7" strokeWidth="1.8" />
        <path d="M3 9h18M8 4v5" stroke="#A855F7" strokeWidth="1.8" strokeLinecap="round" />
        <circle cx="5.5" cy="6.5" r=".75" fill="#A855F7" />
        <rect x="6" y="12" width="7" height="5" rx="1" fill="#A855F7" fillOpacity="0.3" />
        <rect x="15" y="12" width="3" height="2" rx="0.5" fill="#A855F7" />
        <rect x="15" y="15" width="3" height="2" rx="0.5" fill="#A855F7" />
      </svg>
    );
  }

  if (r.includes("back")) {
    return (
      <svg viewBox="0 0 24 24" className={className} fill="none" aria-label="Backend Engineering">
        <rect x="3" y="4" width="18" height="6" rx="2" stroke="#8B5CF6" strokeWidth="1.8" fill="#8B5CF6" fillOpacity="0.1" />
        <rect x="3" y="14" width="18" height="6" rx="2" stroke="#8B5CF6" strokeWidth="1.8" fill="#8B5CF6" fillOpacity="0.1" />
        <circle cx="6.5" cy="7" r="1" fill="#34D399" />
        <circle cx="6.5" cy="17" r="1" fill="#34D399" />
        <path d="M13 7h5M13 17h5" stroke="#8B5CF6" strokeWidth="1.8" strokeLinecap="round" />
        <path d="M9 10v4M15 10v4" stroke="#8B5CF6" strokeWidth="1.5" strokeDasharray="1 2" />
      </svg>
    );
  }

  // Full-Stack
  return (
    <svg viewBox="0 0 24 24" className={className} fill="none" aria-label="Full-Stack Engineering">
      <path d="M12 2L2 7l10 5 10-5-10-5z" stroke="#C084FC" strokeWidth="1.8" strokeLinejoin="round" fill="#C084FC" fillOpacity="0.2" />
      <path d="M2 12l10 5 10-5" stroke="#A855F7" strokeWidth="1.8" strokeLinejoin="round" strokeLinecap="round" />
      <path d="M2 17l10 5 10-5" stroke="#7E22CE" strokeWidth="1.8" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}
